<template><main class="login-shell"><div class="aurora-orb orb-one"></div><div class="aurora-orb orb-two"></div><section class="login-card"><div class="login-brand"><span class="brand-logo"><i></i><i></i><i></i></span><span>Smart <b>CRM</b></span></div><div class="login-divider"></div><span class="eyebrow">WELCOME BACK</span><h1>Sign in to your workspace</h1><p class="muted">Manage every relationship from one clear, powerful workspace.</p><form @submit.prevent="submit"><label>Email address<input v-model.trim="email" type="email" autocomplete="email" placeholder="you@company.com" required /></label><label>Password<input v-model="password" type="password" autocomplete="current-password" placeholder="Enter your password" required /></label><div v-if="error" class="alert alert-danger py-2">{{ error }}</div><button class="primary-btn" :disabled="loading">{{ loading ? 'Signing in…' : 'Continue to Smart CRM' }} <span>→</span></button></form><p class="login-foot"><span>✦</span> Secure access to your customer relationships</p></section></main></template>
<script setup>
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { login } from '../api'
const router = useRouter(), email = ref(''), password = ref(''), error = ref(''), loading = ref(false)
async function submit() { loading.value = true; error.value = ''; try { await login(email.value, password.value); router.push('/') } catch (e) { error.value = e.message } finally { loading.value = false } }
</script>
